    public ResponseEntity<ApiResponse<List<FilingOrder>>> listOrders() {
        JwtAuthFilter.AuthUser caller = currentUser();
        ApiResponse<List<FilingOrder>> response =
                filingOrderService.listOrders(caller.getUserId(), caller.getRole());
        return ResponseEntity.status(response.getCode()).body(response);
    }

    @GetMapping("/{id}")
    public ResponseEntity<ApiResponse<FilingOrder>> getOrder(@PathVariable Long id) {
        ApiResponse<FilingOrder> response = filingOrderService.getOrder(id);
        return ResponseEntity.status(response.getCode()).body(response);
    }

