package com.cloudrecord.platform.service;

import com.cloudrecord.platform.config.JwtUtil;
import com.cloudrecord.platform.dto.ApiResponse;
import com.cloudrecord.platform.dto.LoginRequest;
import com.cloudrecord.platform.dto.LoginResponse;
import com.cloudrecord.platform.entity.User;
import com.cloudrecord.platform.mapper.UserMapper;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Service;

@Service
public class AuthService {

    private final UserMapper userMapper;
    private final PasswordEncoder passwordEncoder;
    private final JwtUtil jwtUtil;

    public AuthService(UserMapper userMapper, PasswordEncoder passwordEncoder, JwtUtil jwtUtil) {
        this.userMapper = userMapper;
        this.passwordEncoder = passwordEncoder;
        this.jwtUtil = jwtUtil;
    }

    public ApiResponse<LoginResponse> login(LoginRequest request) {
        User user = userMapper.findByUsername(request.getUsername());
        if (user == null || !passwordEncoder.matches(request.getPassword(), user.getPassword())) {
            return ApiResponse.error(401, "用户名或密码错误");
        }
        String token = *** user.getUsername(), user.getRole());
        LoginResponse loginResponse = new LoginResponse(token, user.getUsername(), user.getRole());
        return ApiResponse.success("登录成功", loginResponse);
    }
}

package com.cloudrecord.platform.service;

import com.cloudrecord.platform.dto.ApiResponse;
import com.cloudrecord.platform.dto.CreateOrderRequest;
import com.cloudrecord.platform.dto.UpdateStatusRequest;
import com.cloudrecord.platform.entity.FilingOrder;
import com.cloudrecord.platform.mapper.FilingOrderMapper;
import org.springframework.stereotype.Service;

import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;

@Service
public class FilingOrderService {

    private final FilingOrderMapper filingOrderMapper;

    public FilingOrderService(FilingOrderMapper filingOrderMapper) {
        this.filingOrderMapper = filingOrderMapper;
    }

    public ApiResponse<FilingOrder> createOrder(Long userId, CreateOrderRequest request) {
        FilingOrder order = new FilingOrder();
        order.setUserId(userId);
        order.setOrderNo(generateOrderNo());
        order.setStatus("PENDING");
        order.setDomainName(request.getDomainName());
        order.setCompanyName(request.getCompanyName());
        order.setCreatedAt(LocalDateTime.now().truncatedTo(ChronoUnit.SECONDS));
        filingOrderMapper.insert(order);
        return ApiResponse.success("创建成功", order);
    }

    public ApiResponse<List<FilingOrder>> listOrders(Long userId, String role) {
        List<FilingOrder> orders = "ADMIN".equals(role)
                ? filingOrderMapper.findAll()
                : filingOrderMapper.findByUserId(userId);
        return ApiResponse.success(orders);
    }

    public ApiResponse<FilingOrder> getOrder(Long id) {
        FilingOrder order = filingOrderMapper.findById(id);
        if (order == null) {
            return ApiResponse.error(404, "订单不存在");
        }
        return ApiResponse.success(order);
    }

    public ApiResponse<Map<String, Object>> updateStatus(Long id, String role, UpdateStatusRequest request) {
        if (!"ADMIN".equals(role)) {
            return ApiResponse.error(403, "权限不足");
        }
        FilingOrder order = filingOrderMapper.findById(id);
        if (order == null) {
            return ApiResponse.error(404, "订单不存在");
        }
        filingOrderMapper.updateStatus(id, request.getStatus());
        Map<String, Object> data = new LinkedHashMap<>();
        data.put("id", id);
        data.put("status", request.getStatus());
        return ApiResponse.success("更新成功", data);
    }

    public ApiResponse<Map<String, Object>> getProgress(Long id) {
        FilingOrder order = filingOrderMapper.findById(id);
        if (order == null) {
            return ApiResponse.error(404, "订单不存在");
        }
        String status = order.getStatus();
        Map<String, Object> data = new LinkedHashMap<>();
        data.put("orderId", order.getId());
        data.put("orderNo", order.getOrderNo());
        data.put("domainName", order.getDomainName());
        data.put("status", status);
        data.put("steps", buildSteps(status));
        return ApiResponse.success(data);
    }

    private List<Map<String, Object>> buildSteps(String status) {
        List<Map<String, Object>> steps = new ArrayList<>();
        steps.add(step("提交申请", true));
        steps.add(step("初审", !"PENDING".equals(status)));
        steps.add(step("管局审核", "APPROVED".equals(status)));
        steps.add(step("备案完成", "APPROVED".equals(status)));
        return steps;
    }

    private Map<String, Object> step(String name, boolean completed) {
        Map<String, Object> step = new LinkedHashMap<>();
        step.put("step", name);
        step.put("completed", completed);
        return step;
    }

    private String generateOrderNo() {
        String hex = UUID.randomUUID().toString().replace("-", "");
        return "BA" + hex.substring(0, 12);
    }
}

package com.cloudrecord.platform.service;

import com.cloudrecord.platform.dto.ApiResponse;
import com.cloudrecord.platform.dto.CreateSiteRequest;
import com.cloudrecord.platform.entity.FilingOrder;
import com.cloudrecord.platform.entity.SiteInfo;
import com.cloudrecord.platform.mapper.FilingOrderMapper;
import com.cloudrecord.platform.mapper.SiteInfoMapper;
import org.springframework.stereotype.Service;

import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

@Service
public class SiteInfoService {

    private final SiteInfoMapper siteInfoMapper;
    private final FilingOrderMapper filingOrderMapper;

    public SiteInfoService(SiteInfoMapper siteInfoMapper, FilingOrderMapper filingOrderMapper) {
        this.siteInfoMapper = siteInfoMapper;
        this.filingOrderMapper = filingOrderMapper;
    }

    public ApiResponse<SiteInfo> addSite(Long orderId, CreateSiteRequest request) {
        FilingOrder order = filingOrderMapper.findById(orderId);
        if (order == null) {
            return ApiResponse.error(404, "订单不存在");
        }
        SiteInfo siteInfo = new SiteInfo();
        siteInfo.setOrderId(orderId);
        siteInfo.setSiteName(request.getSiteName());
        siteInfo.setSiteUrl(request.getSiteUrl());
        siteInfo.setResponsiblePersonName(request.getResponsiblePersonName());
        siteInfo.setResponsiblePersonIdCard(request.getResponsiblePersonIdCard());
        siteInfo.setResponsiblePersonPhone(request.getResponsiblePersonPhone());
        siteInfo.setResponsiblePersonEmail(request.getResponsiblePersonEmail());
        siteInfo.setSiteType(request.getSiteType());
        siteInfo.setCreatedAt(LocalDateTime.now().truncatedTo(ChronoUnit.SECONDS));
        siteInfoMapper.insert(siteInfo);

        if ("PENDING".equals(order.getStatus())) {
            filingOrderMapper.updateStatus(orderId, "REVIEWING");
        }
        return ApiResponse.success("添加成功", siteInfo);
    }

    public ApiResponse<List<Map<String, Object>>> listSites(Long orderId) {
        FilingOrder order = filingOrderMapper.findById(orderId);
        if (order == null) {
            return ApiResponse.error(404, "订单不存在");
        }
        List<Map<String, Object>> summaries = new ArrayList<>();
        for (SiteInfo siteInfo : siteInfoMapper.findByOrderId(orderId)) {
            Map<String, Object> summary = new LinkedHashMap<>();
            summary.put("id", siteInfo.getId());
            summary.put("orderId", siteInfo.getOrderId());
            summary.put("siteName", siteInfo.getSiteName());
            summary.put("siteUrl", siteInfo.getSiteUrl());
            summary.put("responsiblePersonName", siteInfo.getResponsiblePersonName());
            summary.put("responsiblePersonPhone", siteInfo.getResponsiblePersonPhone());
            summary.put("siteType", siteInfo.getSiteType());
            summary.put("createdAt", siteInfo.getCreatedAt());
            summaries.add(summary);
        }
        return ApiResponse.success(summaries);
    }

    public ApiResponse<SiteInfo> getSite(Long siteId) {
        SiteInfo siteInfo = siteInfoMapper.findById(siteId);
        if (siteInfo == null) {
            return ApiResponse.error(404, "网站信息不存在");
        }
        return ApiResponse.success(siteInfo);
    }
}
